fun longestNonDecreasing(arr: IntArray): IntArray {
    val m = arr.size - 1 // arr indexed 1..m
    val result = IntArray(m + 1)
    val tails = ArrayList<Int>()
    for (i in 1..m) {
        val v = arr[i]
        // upper bound: first index with tails[idx] > v
        var lo = 0
        var hi = tails.size
        while (lo < hi) {
            val mid = (lo + hi) ushr 1
            if (tails[mid] > v) hi = mid else lo = mid + 1
        }
        if (lo == tails.size) tails.add(v) else tails[lo] = v
        result[i] = lo + 1
    }
    return result
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StreamTokenizer(br)
    st.nextToken()
    val n = st.nval.toInt()
    st.nextToken()
    val m = st.nval.toInt()

    val diff = IntArray(m + 2)
    for (i in 0 until n) {
        st.nextToken()
        val l = st.nval.toInt()
        st.nextToken()
        val r = st.nval.toInt()
        diff[l] += 1
        diff[r + 1] -= 1
    }

    val cnt = IntArray(m + 1)
    var run = 0
    for (i in 1..m) {
        run += diff[i]
        cnt[i] = run
    }

    val inc = longestNonDecreasing(cnt)

    val revArr = IntArray(m + 1)
    for (i in 1..m) {
        revArr[i] = cnt[m + 1 - i]
    }

    val decRev = longestNonDecreasing(revArr)

    val dec = IntArray(m + 1)
