fun countUpTo(x: Long): Long {
    // count of odd numbers >=3 up to x
    val oddCount = if (x >= 3) (x + 1) / 2 - 1 else 0L
    // count of multiples of 4 greater than 4, up to x
    val multCount = if (x >= 8) x / 4 - 1 else 0L
    return oddCount + multCount
}

fun findNth(n: Long): Long {
    var lo = 1L
    var hi = 4_000_000_000L
    while (lo < hi) {
        val mid = lo + (hi - lo) / 2
        if (countUpTo(mid) >= n) {
            hi = mid
        } else {
            lo = mid + 1
        }
    }
    return lo
}

