const val MOD = 1_000_000_007L

fun modpow(base: Long, exp: Long, mod: Long): Long {
    var b = base % mod
    if (b < 0) b += mod
    var e = exp
    var result = 1L
    while (e > 0) {
        if (e and 1L == 1L) {
            result = (result * b) % mod
        }
        b = (b * b) % mod
        e = e shr 1
    }
    return result
}

fun main() {
    val br = System.`in`.bufferedReader()
    val line = br.readLine().trim().split(" ")
    val x = line[0].toLong()
