    var xx = x
    var d = 2L
    while (d * d <= xx) {
        if (xx % d == 0L) {
            primes.add(d)
            while (xx % d == 0L) {
                xx /= d
            }
        }
        d++
    }
    if (xx > 1) {
        primes.add(xx)
    }

    var answer = 1L
