    while (e > 0) {
        if (e and 1L == 1L) result = result * b % mod
        b = b * b % mod
        e = e shr 1
    }
    return result
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val a = st.nextToken().toLong()
    val b = st.nextToken().toLong()
    val p = st.nextToken().toLong()
    val x = st.nextToken().toLong()

    // factorize p-1
    var temp = p - 1
    val primeFactors = mutableListOf<Long>()
    var i = 2L
    while (i * i <= temp) {
        if (temp % i == 0L) {
            primeFactors.add(i)
            while (temp % i == 0L) temp /= i
        }
        i++
    }
    if (temp > 1) primeFactors.add(temp)

    var d = p - 1
    for (q in primeFactors) {
        while (d % q == 0L && modpow(a, d / q, p) == 1L) {
            d /= q
        }
    }

    val invA = modpow(a, p - 2, p)
    val invD = modpow(d % p, p - 2, p) // d < p, d >= 1, so d mod p = d, invertible
    val L = d * p

    var count = 0L
    var invAr = 1L // invA^0
    var r = 0L
    while (r < d) {
        val cr = (b * invAr) % p
        var diff = (cr - r) % p
        if (diff < 0) diff += p
        val t0 = diff * invD % p
        var n0 = r + d * t0
        if (n0 == 0L) n0 = L
        if (n0 <= x) {
            count += (x - n0) / L + 1
        }
        invAr = invAr * invA % p
        r++
