fun main() {
    val br = System.`in`.bufferedReader()
    val (nStr, kStr) = br.readLine().trim().split(" ")
    val n = nStr.toInt()
    val kLong = kStr.toLong()
    var kk = BigInteger.valueOf(kLong)

    // Compute number of involutions I[0..n]
    val I = Array(n + 1) { BigInteger.ZERO }
    if (n >= 0) I[0] = BigInteger.ONE
    if (n >= 1) I[1] = BigInteger.ONE
    for (m in 2..n) {
        I[m] = I[m - 1] + BigInteger.valueOf((m - 1).toLong()) * I[m - 2]
    }

    val p = IntArray(n + 1) // 1-indexed
    val remaining = TreeSet<Int>()
    for (i in 1..n) remaining.add(i)

    while (remaining.isNotEmpty()) {
        val i = remaining.first()
        val r = remaining.size

        val countFix = I[r - 1]
        if (kk <= countFix) {
            p[i] = i
            remaining.remove(i)
        } else {
            kk -= countFix
            var found = false
            // iterate over other elements in remaining sorted ascending, excluding i
            val iterCopy = remaining.toList() // snapshot to avoid concurrent modification issues while iterating
            for (j in iterCopy) {
                if (j == i) continue
                if (!remaining.contains(j)) continue
                val countPair = I[r - 2]
                if (kk <= countPair) {
                    p[i] = j
                    p[j] = i
                    remaining.remove(i)
                    remaining.remove(j)
                    found = true
                    break
                } else {
                    kk -= countPair
                }
            }
            if (!found) {
                // Shouldn't happen given valid k, but just in case
                break
            }
        }
    }

    val sb = StringBuilder()
    for (i in 1..n) {
        sb.append(p[i])
        if (i != n) sb.append(' ')
    }
    println(sb.toString())
}
