    val total = 1 shl size
    val sums = LongArray(total)
    for (mask in 0 until total) {
        var s = 0L
        for (i in 0 until size) {
            if ((mask shr i) and 1 == 1) {
                s += arr[i]
            }
        }
        sums[mask] = s % m
    }
    return sums
}

fun main() {
    val br = System.`in`.bufferedReader()
    val (n, m) = br.readLine().trim().split(" ").map { it.toInt() }
    val mLong = m.toLong()
    val a = br.readLine().trim().split(" ").map { it.toLong() }

    val n1 = n / 2
    val n2 = n - n1

    val part1 = a.subList(0, n1)
    val part2 = a.subList(n1, n)

    val sums1 = generateSums(part1, mLong)
    val sums2 = generateSums(part2, mLong)

    sums2.sort()

    var ans = 0L

    val maxY = sums2[sums2.size - 1]

    for (x in sums1) {
        // find largest y such that y <= m - 1 - x
        val limit = mLong - 1 - x
        var lo = 0
        var hi = sums2.size - 1
        var bestIdx = -1
        while (lo <= hi) {
            val mid = (lo + hi) / 2
            if (sums2[mid] <= limit) {
                bestIdx = mid
                lo = mid + 1
            } else {
                hi = mid - 1
            }
        }

        var candidate1 = -1L
        if (bestIdx != -1) {
            candidate1 = x + sums2[bestIdx]
        }

        val candidate2 = (x + maxY) % mLong

        val best = if (candidate1 > candidate2) candidate1 else candidate2

        if (best > ans) {
            ans = best
        }
    }

    println(ans)
}
