fun main() {
    val br = System.`in`.bufferedReader()
    val (n, t) = br.readLine().trim().split(" ").map { it.toInt() }

    // dp[y-1][dir][peak][valley] = count
    // dir: 0 = down (y_curr < y_prev), 1 = up (y_curr > y_prev)
    var dp = Array(4) { Array(2) { Array(t + 1) { LongArray(t + 1) } } }

    // initialize for first two points (i=1 and i=2)
    for (y1 in 1..4) {
        for (y2 in 1..4) {
            if (y2 == y1) continue
            val dir = if (y2 > y1) 1 else 0
            dp[y2 - 1][dir][0][0] += 1L
        }
    }

    if (n == 2) {
        // Not per constraints (n>=3), but just in case
        var total = 0L
        for (y in 0..3) for (d in 0..1) {
            total += dp[y][d][0][0]
        }
        println(total)
        return
    }

    for (i in 3..n) {
        val ndp = Array(4) { Array(2) { Array(t + 1) { LongArray(t + 1) } } }
        for (yPrev in 1..4) {
            for (dirPrev in 0..1) {
                for (peak in 0..t) {
                    for (valley in 0..t) {
                        val cur = dp[yPrev - 1][dirPrev][peak][valley]
                        if (cur == 0L) continue
                        for (yCurr in 1..4) {
                            if (yCurr == yPrev) continue
                            val dirCurr = if (yCurr > yPrev) 1 else 0
                            var np = peak
                            var nv = valley
                            if (dirPrev == 1 && dirCurr == 0) np++
                            if (dirPrev == 0 && dirCurr == 1) nv++
                            if (np > t || nv > t) continue
                            ndp[yCurr - 1][dirCurr][np][nv] += cur
                        }
                    }
                }
            }
        }
        dp = ndp
    }

    var answer = 0L
    val neededValley = t - 1
    if (neededValley >= 0 && neededValley <= t) {
        for (y in 0..3) {
            for (d in 0..1) {
                answer += dp[y][d][t][neededValley]
            }
        }
    }

    println(answer)
}
