        list.add(cur.toString().toLong())
        return
    }
    cur.append('4')
    genLucky(len, cur, list)
    cur.deleteCharAt(cur.length - 1)
    cur.append('7')
    genLucky(len, cur, list)
    cur.deleteCharAt(cur.length - 1)
}

fun luckyNumbersUpTo(n: Long): List<Long> {
    val list = mutableListOf<Long>()
    for (len in 1..9) {
        genLucky(len, StringBuilder(), list)
    }
    return list.filter { it <= n }
}

fun main() {
