    val line = br.readLine()!!.trim()
    val st = StringTokenizer(line)
    val n = st.nextToken().toLong()
    val k = st.nextToken().toLong()

    val fact = LongArray(14)
    fact[0] = 1
    for (i in 1..13) {
        fact[i] = fact[i - 1] * i
    }

    // Check validity
    if (n < 13) {
        val nf = fact[n.toInt()]
        if (k > nf) {
            println(-1)
            return
        }
    }

    // Determine m: smallest m such that fact[m] >= k
    var m = 0
    while (m <= 13 && fact[m] < k) {
        m++
    }
    // m should be <= n by construction (validity checked above for n<13, and for n>=13, m<=13<=n)

    val tailStart = n - m

    // Build available list for the tail part
    val avail = mutableListOf<Long>()
    var v = tailStart + 1
    while (v <= n) {
        avail.add(v)
        v++
    }

    var remaining = k - 1
    val result = mutableListOf<Long>()
    var i = m
    while (i >= 1) {
        val f = fact[i - 1]
        val idx = (remaining / f).toInt()
        remaining %= f
        result.add(avail[idx])
        avail.removeAt(idx)
        i--
    }

    val luckyList = luckyNumbersUpTo(n)
    var count = 0

    for (L in luckyList) {
        if (L <= tailStart) {
            // a_L = L, which is lucky by definition of L being in luckyList
            count++
        } else {
            val idx = (L - tailStart - 1).toInt()
            if (idx in result.indices) {
                val value = result[idx]
                if (isLucky(value)) {
                    count++
                }
            }
        }
    }

    println(count)
