    while (i * i <= num) {
        if (num % i == 0L) {
            var cnt = 0
            while (num % i == 0L) {
                num /= i
                cnt++
            }
            factors[i] = cnt
        }
        i++
    }
    if (num > 1L) {
        factors[num] = (factors[num] ?: 0) + 1
    }

    var answer = 1L

    for ((p, e) in factors) {
        // dp array over exponents 0..e
        var dp = LongArray(e + 1)
        dp[e] = 1L

        // precompute inverses for 1..(e+1)
        val inv = LongArray(e + 2)
        for (j in 1..(e + 1)) {
            inv[j] = modInverse(j.toLong(), MOD)
        }

        for (step in 1..k) {
            val c = LongArray(e + 1)
            for (idx in 0..e) {
                c[idx] = dp[idx] * inv[idx + 1] % MOD
            }
            val newDp = LongArray(e + 1)
            var suffix = 0L
            for (j in e downTo 0) {
                suffix = (suffix + c[j]) % MOD
                newDp[j] = suffix
            }
            dp = newDp
        }

        val pMod = p % MOD
        var contrib = 0L
        var pPow = 1L // p^0
        for (j in 0..e) {
            contrib = (contrib + dp[j] * pPow) % MOD
            pPow = pPow * pMod % MOD
        }

        answer = answer * contrib % MOD
    }

    println(answer)
}
