import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val m = scanner.nextInt()

    val rows = minOf(n, m)
    val cols = maxOf(n, m)
    val full = (1 shl rows) - 1
    val size = 1 shl rows
    val INF = Int.MAX_VALUE / 2

    // dp[S][U] = min cost, S = dominators chosen in current column,
    // U = bitmask of cells in current column not yet dominated (need next column to cover)
    var dp = Array(size) { IntArray(size) { INF } }

    for (s0 in 0 until size) {
        val vert = ((s0 shl 1) or (s0 shr 1)) and full
        val dominated = (s0 or vert) and full
        val u0 = full and dominated.inv()
        val cost = Integer.bitCount(s0)
        if (cost < dp[s0][u0]) dp[s0][u0] = cost
    }

    for (col in 1 until cols) {
        val ndp = Array(size) { IntArray(size) { INF } }
        for (sp in 0 until size) {
            for (u in 0 until size) {
                val cur = dp[sp][u]
                if (cur >= INF) continue
                for (sn in 0 until size) {
                    if ((u and sn) != u) continue // sn must cover all undominated bits from previous column
                    val vert = ((sn shl 1) or (sn shr 1)) and full
                    val dominated = (sn or sp or vert) and full
                    val unext = full and dominated.inv()
                    val cost = cur + Integer.bitCount(sn)
                    if (cost < ndp[sn][unext]) ndp[sn][unext] = cost
                }
            }
        }
        dp = ndp
    }

    var best = INF
    for (s in 0 until size) {
        if (dp[s][0] < best) best = dp[s][0]
    }

    println(n * m - best)
}
